### 3. Harden the Express stack

```js
const express = require('express');
const helmet = require('helmet');
const cors   = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

// -------------- Security middleware -----------------
app.disable('x-powered-by');          // hide framework signature
app.use(helmet());                    // set safe HTTP headers
app.use(cors({                         // restrict origins in prod
  origin: process.env.NODE_ENV === 'production'
          ? ['https://my‑app.example.com']
          : '*',
  methods: ['GET','POST','PUT','DELETE'],
}));
app.use(morgan('combined'));           // request logging

// Rate limiting: 100 requests per 15 min per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---------------------------------------------------
```

**Why?**  
* `helmet` sets headers such as `Content‑Security‑Policy`, `X‑Content-Type-Options`, `Referrer-Policy`, etc.  
* `cors` prevents the API from being called from unauthorized origins.  
* `rateLimit` mitigates brute‑force and DoS attacks.  
* `morgan` creates audit logs required by OWASP‑A09.

---

### 4. Add **authentication & authorization** for sensitive routes

Assuming you have a JWT‑based auth scheme (replace with whichever your system uses):

```js
const jwt = require('jsonwebtoken');

// Simple middleware – replace with your own secret/key management
function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
  }
  const token = authHeader.split(' ')[1];
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid token' });
  }
}

// Apply to routes that need protection
app.get('/users', authenticate, (req, res) => {
  // You may also filter data based on role/permissions
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Result:**  
Only callers presenting a valid JWT can retrieve `/users`. Extend the middleware to enforce role‑based access (e.g., `admin` role only).

