### 7. Input validation & sanitisation (future‑proof)

Even though the current routes accept no user data, it’s good practice to have a validation layer ready:

```js
const { body, param, query, validationResult } = require('express-validator');

function validate(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
}

// Example for a POST /users route that creates a user
app.post(
  '/users',
  authenticate,
  [
    body('name').trim().isLength({ min: 1 }).escape(),
    body('email').isEmail().normalizeEmail(),
  ],
  validate,
  (req, res) => {
    // safe to use req.body now
    // …
  }
);
```

**Benefits:**  
- Mitigates injection attacks (SQL, NoSQL, command injection).  
- Removes XSS vectors when data is rendered in a UI later.

