const app = express();

// Load config *once* before the HTTP server starts.
const getConfig = require('./src/config'); // ← the promise exported above

(async () => {
  const config = await getConfig; // <-- resolves all secrets

  // You can now use the secrets safely, e.g. initialise a DB client:
  // const db = new PgClient({ connectionString: config.databaseUrl });
