  // … (your health/users routes)

  // ----------------- Error handling (unchanged) -----------------
  app.use(errors());
  app.use((err, req, res, next) => {
    console.error(err);
    const msg = process.env.NODE_ENV === 'production'
      ? 'Internal Server Error'
