// secret-loader.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const REGION = process.env.AWS_REGION || 'us-east-1';
const client = new SecretsManagerClient({ region: REGION });

/**
 * Retrieves a secret from AWS Secrets Manager.
 * The secret value can be a plain string or a JSON object.
 *
 * @param {string} secretName - The name or ARN of the secret.
 * @returns {Promise<any>} - Parsed secret (object) or raw string.
 */
async function getSecret(secretName) {
  const command = new GetSecretValueCommand({ SecretId: secretName });
  const response = await client.send(command);
  if (!response.SecretString) {
    throw new Error(`Secret ${secretName} has no string value`);
  }

  try {
    // Try to parse JSON (common pattern for multiple keys)
    return JSON.parse(response.SecretString);
  } catch {
    // Fallback: plain string
    return response.SecretString;
  }
}

module.exports = { getSecret };
```

3. **Integrate it into `app.js` (early, before the server starts)**:

```js
// app.js (top of the file)
require('dotenv').config();               // still load non‑secret config vars
const { getSecret } = require('./secret-loader');

(async () => {
  // -----------------------------------------------------------------
  // 1️⃣ Retrieve the JWT secret from Secrets Manager.
  //    Expect the secret to be either a plain string or JSON like:
  //    { "jwtSecret": "super‑strong‑random‑value" }
  // -----------------------------------------------------------------
  const secretName = process.env.JWT_SECRET_NAME || 'myapp/jwt';
  const secretValue = await getSecret(secretName);

  const JWT_SECRET = typeof secretValue === 'string'
    ? secretValue
    : secretValue.jwtSecret;

  if (!JWT_SECRET) {
    console.error('❌ JWT secret could not be loaded – aborting');
    process.exit(1);
  }

  // Expose it for the rest of the app (you could also use a global config object)
  process.env.JWT_SECRET = JWT_SECRET;

  // -----------------------------------------------------------------
  // 2️⃣ Continue with the normal Express bootstrap (the rest of the file
  //    stays exactly the same – just make sure you call `app.listen` at
  //    the end of this IIFE or export the app for testing).
  // -----------------------------------------------------------------
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`🚀 Server listening on port ${PORT}`);
  });
})();
```

**What this gives you**

* **No secret lives in source control** – the JWT secret lives only in AWS Secrets Manager.
* **Rotation** – you can replace the secret value in the manager; the next container restart will pick it up automatically.
* **Auditability** – AWS logs every `GetSecretValue` call.

*Optional*: configure the AWS SDK to use **IAM roles** attached to the EC2/ECS task, eliminating the need for static access keys.

