// 1️⃣  Core imports
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken'); // Example auth lib
const { body, param, validationResult } = require('express-validator');

const app = express();

// ------------------------------------------------------------
// 2️⃣  Global middlewares
app.use(helmet());                        // Security headers
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(morgan('combined'));              // Structured request logging

// CORS – only allow trusted origins (adjust as needed)
app.use(
  cors({
    origin: ['https://myapp.example.com'],
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);

// Rate limiting – 100 requests per 15 min per IP (tune for your traffic)
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', apiLimiter); // Apply to any future /api routes

// ------------------------------------------------------------
// 3️⃣  Simple auth middleware (JWT example)
//    In a real app you’d put this in its own file.
const AUTH_SECRET = process.env.AUTH_SECRET || 'CHANGE_ME_TO_STRONG_RANDOM';

function authenticateJWT(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.sendStatus(401); // No token

  const token = authHeader.split(' ')[1];
  jwt.verify(token, AUTH_SECRET, (err, user) => {
    if (err) return res.sendStatus(403); // Invalid/expired
    req.user = user;
    next();
  });
}

// ------------------------------------------------------------
// 4️⃣  Routes
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

