  res.json(users);
});

/**
 * Example of a POST endpoint that demonstrates input validation &
 * safe handling (prevents injection, XSS, etc.).
 */
app.post(
  '/api/messages',
  [
    // ---- Validation chain (express‑validator) ----
    body('subject')
      .trim()
      .isLength({ min: 1, max: 150 })
      .withMessage('Subject must be 1‑150 characters'),
    body('body')
      .trim()
      .isLength({ min: 1, max: 2000 })
      .withMessage('Message body must be 1‑2000 characters'),
    // sanitize input to neutralise HTML/JS injection
    body('subject').escape(),
    body('body').escape(),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // Respond with 400 and detailed validation errors (no internal info)
      return res.status(400).json({ errors: errors.array() });
    }

    // Safe to use req.body now – all fields are validated & escaped.
    // Insert into DB using a parameterised query / ORM (example omitted).
    res.status(201).json({ message: 'Message stored' });
  }
);

// ------------------------------------------------------------
// 5️⃣  Central error handler (must be after all routes)
app.use((err, req, res, next) => {
  console.error(err); // Log stack trace securely (e.g., to a file or SIEM)

  // Do **not** leak internal details to the client
  const status = err.status || 500;
  res.status(status).json({
    error: status === 500 ? 'Internal Server Error' : err.message,
  });
});

// ------------------------------------------------------------
// 6️⃣  Server start – note we keep HTTP here for simplicity.
//      Deploy behind a TLS terminator (nginx, ALB, etc.).
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
