  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/health', apiLimiter);
app.use('/users', apiLimiter);

// ------------------------------------------------------------------
// 4. Authentication (protect /users)
// ------------------------------------------------------------------
const auth = jwt({
  secret: process.env.JWT_SECRET || 'CHANGE_THIS_SECRET',
  algorithms: ['HS256'],
