app.use(apiLimiter);

// Body parsing (needed for any future POST/PUT)
app.use(express.json());

// ---------- 3. Simple authentication middleware ----------
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed token' });
  }
  const token = authHeader.split(' ')[1];
  try {
    // Verify with a secret stored in .env (e.g., JWT_SECRET=super-secret)
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};

// ---------- 4. Routes ----------
app.get('/health', (req, res) => {
  // Minimal info – avoids leaking internal config
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', authenticate, (req, res) => {
  // In a real app, fetch from DB with proper RBAC checks
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ---------- 5. Central error handler ----------
app.use((err, req, res, next) => {
  // Log the error (stack only in dev)
  logger.error({ err, req }, 'Unhandled error');
  const status = err.status || 500;
  const response = {
    error: status === 500 ? 'Internal server error' : err.message,
  };
  // Hide stack traces from callers in production
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }
  res.status(status).json(response);
});

// ---------- 6. Server start ----------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server listening on port ${PORT}`);
});

// Graceful shutdown (helps avoid DOS via lingering sockets)
process.on('SIGTERM', () => {
  logger.info('SIGTERM received – closing server');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

module.exports = app;
```

