```js
// config.js – central place to read all runtime config
require('dotenv').config();   // loads .env only in local/dev, ignored in prod

module.exports = {
  port: process.env.PORT || 3000,
  host: process.env.HOST || '0.0.0.0',
  jwtSecret: process.env.JWT_SECRET,               // required for auth
  corsOrigin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  // add any other secrets (DB_URL, API_KEY, etc.) here
