### 1. Add Security‑Focused Middleware

```js
const express = require('express');
const helmet = require('helmet');          // Secure HTTP headers
const morgan = require('morgan');          // Request logging
const rateLimit = require('express-rate-limit'); // Basic DoS protection
const app = express();

// Helmet must be loaded early
app.use(helmet());

// Log all incoming requests (combined format)
app.use(morgan('combined'));

// Rate limiting (e.g., max 100 requests per 15 minutes per IP)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Parse JSON bodies (if you accept POST/PUT later)
