### 2. Protect Sensitive Endpoints with Authentication

Below is a simple JWT‑based guard you can expand upon:

```js
const jwt = require('jsonwebtoken');

// Middleware to verify JWT
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (!token) return res.sendStatus(401); // No token

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.sendStatus(403); // Invalid token
    req.user = user;                     // attach payload
    next();
  });
}

// Example: protect the /users endpoint
app.get('/users', authenticateToken, (req, res) => {
  // Access control: only admin role can view list
  if (req.user.role !== 'admin') {
    return res.sendStatus(403);
  }
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});
```

> **Tip:** Store `JWT_SECRET` in a secrets manager, not in a plain `.env` file.

### 3. Centralised Error Handling (Avoid Information Leakage)

```js
// Generic error handler – must be after all routes
app.use((err, req, res, next) => {
  console.error(err);               // log internally
  const status = err.status || 500;
  const message = status === 500 ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: message });
});
```

### 4. Enforce HTTPS (If Node directly terminates TLS)

If you terminate TLS in the Node process, redirect HTTP to HTTPS:

```js
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.secure) {
      return next();
    }
    res.redirect(`https://${req.headers.host}${req.url}`);
  });
}
```

In many deployments you’d instead put a reverse proxy (NGINX, ALB) in front of the app that handles TLS.

### 5. Secure Secret Management

1. **Remove direct `.env` usage** – don’t keep production secrets in source‑controlled files.  
2. **Use a secrets manager** (AWS Secrets Manager, Azure Key Vault, HashiCorp Vault, etc.).  
3. At startup, fetch secrets via the provider’s SDK and inject them into `process.env` **in memory only**.

Example (AWS Secrets Manager):

