// app.js – Secure baseline version
require('dotenv').config();                                 //  <-- Load .env
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const Joi = require('joi'); // for input validation (future use)

const app = express();

/* --------------------------------------------------------------
 * 1️⃣  Global security middlewares
 * ------------------------------------------------------------ */
app.use(helmet());                     // A05 – security headers
app.use(express.json());               // Parse JSON bodies (future POST/PUT)
app.use(morgan('combined'));           // A09 – logging

// CORS – only allow trusted origins (adjust as needed)
const allowedOrigins = process.env.CORS_ORIGINS?.split(',') || [];
app.use(
  cors({
    origin: (origin, callback) => {
      // Allow requests with no origin (e.g., curl, postman) OR whitelist
      if (!origin || allowedOrigins.includes(origin)) {
        callback(null, true);
      } else {
        callback(new Error('Not allowed by CORS'));
      }
    },
    credentials: true,
  })
);

// Rate limiting – 100 req/min per IP (tweak for your scenario)
const limiter = rateLimit({
  windowMs: 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

/* --------------------------------------------------------------
 * 2️⃣  Helper: JWT verification middleware (for protected routes)
 * ------------------------------------------------------------ */
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>
  if (!token) return res.status(401).json({ error: 'Missing token' });

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user; // attach decoded payload
    next();
  });
}

/* --------------------------------------------------------------
 * 3️⃣  Routes
 * ------------------------------------------------------------ */

// Health endpoint – public, no auth needed
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Example protected endpoint.
 * - Demonstrates authentication (A01, A07)
 * - Uses Joi for input validation (future expansion)
 */
app.get('/users', authenticateToken, (req, res) => {
  // Static data for demo – in real apps fetch from DB with parameterized queries
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

/* --------------------------------------------------------------
 * 4️⃣  Error handling (must be after all routes)
 * ------------------------------------------------------------ */
app.use((err, req, res, next) => {
  console.error(err); // you could also pipe to a log aggregation service

  // Do not expose stack traces in production
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production' ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: message });
});

/* --------------------------------------------------------------
 * 5️⃣  Server start – port from env, fallback to 3000
 * ------------------------------------------------------------ */
