const express   = require('express');
const helmet    = require('helmet');               // Security headers (OWASP A05)
const rateLimit = require('express-rate-limit');   // Brute‑force / DoS protection (A05)
const cors      = require('cors');                  // Controlled cross‑origin access (A05)
const morgan    = require('morgan');                // Request logging (A09)
const dotenv    = require('dotenv');                // Config via env vars (avoid hard‑coding)

dotenv.config(); // Loads .env file if present

