// 3️⃣ CORS – only allow origins you trust
//   * In a public API you could set `origin: '*` but that defeats the purpose of CORS.
//   * For this example we allow any origin but you should replace with your domain(s).
app.use(cors({
  origin: process.env.CORS_ORIGIN || '*', // e.g. "https://myapp.example.com"
  methods: ['GET'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// ---------------------------------------------------
// 4️⃣ Rate limiting – 100 requests per 15 minutes per IP (adjust as needed)
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,   // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});
app.use(apiLimiter);

// ---------------------------------------------------
// 5️⃣ Request logging (combined format) – helps with A09
app.use(morgan('combined'));

// ---------------------------------------------------
// 6️⃣ JSON body parser – not needed now but useful for future POST/PUT routes
app.use(express.json());

// ---------------------------------------------------
// 7️⃣ Routes (functionality unchanged)
app.get('/health', (req, res) => {
  // Do not expose internal stack traces – use a simple status payload
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example: protect /users with a very simple token‑based auth (replace with your auth scheme)
function requireAuth(req, res, next) {
  const authHeader = req.headers.authorization || '';
  const token = authHeader.replace(/^Bearer\s+/i, '');

  // In production you would verify a JWT, look up a session, etc.
  // Here we just compare against an environment variable for illustration.
  if (token && token === process.env.API_TOKEN) {
    return next();
  }

  // No valid token → 401 Unauthorized
  return res.status(401).json({ error: 'Unauthorized' });
}

// Apply the auth middleware only to routes that expose sensitive data
