  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com' },
  ]);
});

// ---------------------------------------------------
// 8️⃣ Global error handler – prevents stack traces leaking to clients (A05, A09)
app.use((err, req, res, next) => {
  console.error(err); // Logs full error for ops team (do not send to client)
  res.status(err.status || 500).json({ error: 'Internal Server Error' });
});

// ---------------------------------------------------
// 9️⃣ Server start – enforce HTTPS when behind a proxy (e.g., Heroku, AWS ELB)
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

