* Exposes the retrieved values via `process.env` (so existing code can keep using `process.env.XYZ`).

```js
// secret-loader.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const isProd = process.env.NODE_ENV === 'production';

/**
 * Load a secret from AWS Secrets Manager.
 * @param {string} secretId - The full ARN or name of the secret.
 * @returns {Promise<string>} The secret's plaintext value.
 */
async function loadAwsSecret(secretId) {
  const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
  const command = new GetSecretValueCommand({ SecretId: secretId });
  const response = await client.send(command);
  return response.SecretString; // assuming string, not binary
}

/**
 * Populate `process.env` with the required secrets.
 * In production we pull from Secrets Manager,
 * otherwise we load a local .env file (for developer convenience only).
 */
async function initSecrets() {
  if (isProd) {
    // Example secret names – replace with your actual secret identifiers
    const secretMap = {
      DATABASE_URL:      'prod/database-url',
      AWS_ACCESS_KEY_ID: 'prod/aws-access-key-id',
      AWS_SECRET_ACCESS_KEY: 'prod/aws-secret-access-key',
      ANTHROPIC_API_KEY: 'prod/anthropic-api-key',
      STRIPE_SECRET_KEY: 'prod/stripe-secret-key',
      LOGFIRE_TOKEN:     'prod/logfire-token',
    };

    // Parallel fetch (you can also fetch sequentially for finer error handling)
    await Promise.all(Object.entries(secretMap).map(async ([envVar, secretId]) => {
      try {
        const secret = await loadAwsSecret(secretId);
        process.env[envVar] = secret;
      } catch (err) {
        console.error(`Failed to load secret ${secretId}:`, err);
        process.exit(1); // Fail fast – you don’t want to start without required secrets
      }
    }));
  } else {
    // Development / test – load from a .env file (never commit real secrets!)
    // dotenv-safe ensures all required keys exist.
    const dotenvSafe = require('dotenv-safe');
    dotenvSafe.config({
      path: '.env.test',          // point to the test file
      example: '.env.example',   // you can create this to list required vars
      allowEmptyValues: false,
    });
  }
}

// Export a Promise that resolves when secrets are ready
module.exports = initSecrets();
```

