## 2️⃣ Recommended way to load secrets from a **managed secrets store**

Below are three common, production‑grade options (AWS Secrets Manager, HashiCorp Vault, and Google Secret Manager). Choose the one that matches your cloud provider or infrastructure.

### 2.1. AWS Secrets Manager (Node .js example)

1. **Create a secret** in the AWS console that holds a JSON document, e.g.

   ```json
   {
     "DATABASE_URL": "postgres://admin:real‑db‑secret@db.internal:5432/production",
     "AWS_ACCESS_KEY_ID": "AKIA…",
     "AWS_SECRET_ACCESS_KEY": "real‑aws‑secret",
     "ANTHROPIC_API_KEY": "sk‑ant‑real‑api‑key",
     "STRIPE_SECRET_KEY": "REDACTED_STRIPE_LIVE",
     "LOGFIRE_TOKEN": "real‑logfire‑token"
   }
   ```

2. **Grant the container/EC2 instance an IAM role** with `secretsmanager:GetSecretValue` on that secret.

3. **Load the secret at startup** (once, then cache it).

   ```js
   // secrets.js
   const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

   const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

   /**
    * Retrieves the secret JSON from AWS Secrets Manager and populates process.env.
    * Returns a promise that resolves when the secret is loaded.
    */
   async function loadAwsSecrets(secretId) {
     const command = new GetSecretValueCommand({ SecretId: secretId });
     const { SecretString } = await client.send(command);
     if (!SecretString) throw new Error('Secret value is empty');

     const secretObj = JSON.parse(SecretString);
     // Copy each key into process.env (do **not** overwrite existing vars)
     for (const [key, value] of Object.entries(secretObj)) {
       if (!process.env[key]) {
         process.env[key] = value;
       }
     }
   }

   module.exports = { loadAwsSecrets };
   ```

4. **Bootstrap the app**:

   ```js
   // server.js (or the top of app.js)
   const { loadAwsSecrets } = require('./secrets');

   // Replace this with the ARN or name of your secret
   const SECRET_ID = process.env.SECRETS_MANAGER_ID || 'my-app/secrets';

   loadAwsSecrets(SECRET_ID)
     .then(() => {
       // Now start the Express server – all secret values are in process.env
       require('./app'); // <-- your existing Express app
     })
     .catch(err => {
       console.error('Failed to load secrets from AWS Secrets Manager:', err);
       process.exit(1);
     });
   ```

5. **Remove the `.env` loading** (or keep it only for local development). In `package.json` you may have a separate `start:dev` script that still uses `dotenv`.

### 2.2. HashiCorp Vault (Node .js example)

```js
// vaultSecrets.js
const vault = require('node-vault')({
  apiVersion: 'v1',
  endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
  token: process.env.VAULT_TOKEN, // Prefer AppRole / Kubernetes auth, not a static token
});

async function loadVaultSecrets(path = 'secret/data/my-app') {
  const { data } = await vault.read(path);
  // Vault KV version 2 stores data under .data.data
  const secrets = data?.data || data;
  for (const [k, v] of Object.entries(secrets)) {
    if (!process.env[k]) process.env[k] = v;
  }
}

module.exports = { loadVaultSecrets };
```

Bootstrap similarly to the AWS example:

```js
const { loadVaultSecrets } = require('./vaultSecrets');
loadVaultSecrets()
  .then(() => require('./app'))
  .catch(err => {
    console.error('Vault secret load error:', err);
    process.exit(1);
  });
```

### 2.3. Google Secret Manager (Node .js example)

```js
// gcpSecrets.js
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

const client = new SecretManagerServiceClient();

async function loadGcpSecrets(projectId, secretNames) {
  for (const name of secretNames) {
    const [version] = await client.accessSecretVersion({
      name: `projects/${projectId}/secrets/${name}/versions/latest`,
    });
    const payload = version.payload.data.toString('utf8');
    // Expect each secret to be a single value (e.g., DATABASE_URL)
    process.env[name] = payload;
  }
}

module.exports = { loadGcpSecrets };
```

