## 3️⃣ Suggested Refactored `app.js`

Below is a **complete but still minimal** version that incorporates the above hardening steps while preserving the existing functionality (health check & static user list).

```js
// app.js – Hardened version
/* eslint-disable no-console */

require('dotenv').config();               // Load .env (optional)
const express   = require('express');
const helmet    = require('helmet');
const cors      = require('cors');
const rateLimit = require('express-rate-limit');
const pino      = require('pino');

const logger = pino({ level: process.env.LOG_LEVEL || 'info' });
const app    = express();

// -------------------- Security Middleware --------------------
app.use(helmet());

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
}));

app.use(express.json({ limit: '1mb' }));

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests' },
});
app.use(limiter);

// -------------------- Logging --------------------
app.use((req, _res, next) => {
  logger.info({ method: req.method, url: req.originalUrl, ip: req.ip });
  next();
});

// -------------------- HTTPS enforcement (prod) --------------------
if (process.env.NODE_ENV === 'production') {
  app.enable('trust proxy');
  app.use((req, res, next) => {
    if (req.secure) return next();
    res.redirect(301, `https://${req.headers.host}${req.originalUrl}`);
  });
}

// -------------------- Routes --------------------
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (_req, res) => {
  // In a real app this would be fetched from a DB with proper RBAC.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com' }
  ]);
});

// -----------------------------------------------------------------
// Central error handler – hides stack traces from callers.
app.use((err, _req, res, _next) => {
  logger.error(err);
  const status = err.status || 500;
  res.status(status).json({
    error: status === 500 ? 'Internal Server Error' : err.message
  });
});

// -------------------- Server bootstrap --------------------
const server = app.listen(process.env.PORT || 3000, () => {
  logger.info(`Server running on port ${server.address().port}`);
});

// Graceful shutdown
function shutdown() {
  logger.info('Received termination signal – shutting down...');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app;
```

**What changed?**

- Added **Helmet**, **CORS**, **rate‑limiting**, **HTTPS enforcement**, and **structured logging**.  
- Centralized **error handling** to avoid leaking stack traces.  
- Implemented **graceful shutdown**.  
- Wrapped the server start in a variable for clean shutdown.  
- Clean separation of concerns – security middleware at the top, routes later.

